import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Br18A9IS.js";var i=JSON.parse(`{"title":"Holodeck in Dev Mode","description":"","frontmatter":{"title":"Holodeck in Dev Mode"},"headers":[],"relativePath":"guides/the-manual/cookbook/holodeck-in-dev-mode.md","filePath":"guides/the-manual/cookbook/holodeck-in-dev-mode.md"}`),a={name:`guides/the-manual/cookbook/holodeck-in-dev-mode.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="holodeck-in-dev-mode" tabindex="-1">Holodeck in dev mode <a class="header-anchor" href="#holodeck-in-dev-mode" aria-label="Permalink to “Holodeck in dev mode”">​</a></h1><p>An app whose dev server also serves its test page can run the suite in the browser. You start <code>vite</code> with <code>pnpm start</code> and open <code>/tests</code>, which is <code>http://localhost:4200/tests</code> in the examples here. If your tests use <a href="/pr-preview/pr-11205/guides/the-manual/testing/">holodeck</a>, that page fails when the suite runs, even though <code>pnpm test</code> passes.</p><p>This recipe starts holodeck next to the dev server so both ways of running the suite work.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to “Before you start”">​</a></h2><p>This page assumes holodeck already works under <code>pnpm test</code>, with testem launching it as <a href="/pr-preview/pr-11205/guides/the-manual/testing/server-setup#with-testem">Server setup</a> describes. The examples use the fixed port <code>7358</code>. The browser you open <code>/tests</code> in has to trust the local certificate from <a href="/pr-preview/pr-11205/guides/the-manual/testing/server-setup#trust-a-local-certificate">Trust a local certificate</a>. <code>tests/test-helper.js</code> points requests at the mock server:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { setConfig } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/holodeck&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { setBuildURLConfig } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/utilities&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MOCK_HOST</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://localhost:7358&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setBuildURLConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ host: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MOCK_HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, namespace: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;api&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ host: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MOCK_HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><h2 id="why-the-dev-server-fails" tabindex="-1">Why the dev server fails <a class="header-anchor" href="#why-the-dev-server-fails" aria-label="Permalink to “Why the dev server fails”">​</a></h2><p><code>testem.js</code> is the only thing that calls <code>holodeck.launchProgram</code>, and only <code>pnpm test</code> runs testem. <code>vite</code> serves the test page but starts nothing on <code>7358</code>, so every call to <code>mock()</code> fails to reach the server. The page reports two errors per test:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Promise rejected during &quot;the feed renders, and composing a post reloads it&quot;: Failed to fetch</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Global afterEach failed on the feed renders, and composing a post reloads it: Error: Holodeck: this test declared mocks it never requested.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	GET api/users?page%5Bsize%5D=100&amp;sort=handle (mocked 1, requested 0)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A mock that is never requested proves nothing. Remove it, or make the request it describes.</span></span></code></pre></div><p><code>Failed to fetch</code> is how Chrome reports the unreachable server. Safari reports it as <code>Load failed</code>. The second error follows from the first: the test declared the mock, but its request never reached a server. The mock itself is fine.</p><h2 id="add-a-launcher-script" tabindex="-1">Add a launcher script <a class="header-anchor" href="#add-a-launcher-script" aria-label="Permalink to “Add a launcher script”">​</a></h2><p>Create <code>scripts/holodeck.mjs</code> in the app:</p><div class="language-js"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> holodeck </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/holodeck&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> holodeck.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchProgram</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ port: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7358</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><p>The server runs in a worker thread, which keeps the process alive after <code>launchProgram</code> resolves. Holodeck handles <code>Ctrl+C</code> itself and prints <code>Holodeck program ended</code>, so the script needs no signal handling.</p><p>The port has to match in three places: this script, <code>testem.js</code>, and <code>MOCK_HOST</code> in <code>tests/test-helper.js</code>. Holodeck binds only the port it is given, and the browser only knows the address in <code>MOCK_HOST</code>. If yours differ from <code>7358</code>, copy the port from <code>testem.js</code>.</p><h2 id="run-it-with-the-dev-server" tabindex="-1">Run it with the dev server <a class="header-anchor" href="#run-it-with-the-dev-server" aria-label="Permalink to “Run it with the dev server”">​</a></h2><p>Add a script to <code>package.json</code> that starts both processes with <a href="https://www.npmjs.com/package/concurrently" target="_blank" rel="noreferrer"><code>concurrently</code></a>. If your app doesn&#39;t have it yet, add it with <code>pnpm add -D concurrently</code>.</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scripts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vite&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vite build --mode development &amp;&amp; testem ci --port 0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;test:dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;concurrently --names vite,holodeck --kill-others </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">node ./scripts/holodeck.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Run <code>pnpm test:dev</code>, then open <code>http://localhost:4200/tests</code>. The holodeck banner prints first:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[holodeck] 	Holodeck Access Granted</span></span>
<span class="line"><span>[holodeck] 		program: web</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[holodeck] 	Serving Holodeck HTTP Mocks from https://localhost:7358</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[vite]   ➜  Local:   http://localhost:4200/</span></span></code></pre></div><p><code>--kill-others</code> stops Vite when holodeck exits, and holodeck when Vite exits. You never end up with a dev server whose tests fail because the mock server quietly died. <code>Ctrl+C</code> stops both.</p><p>The package script runs from the app&#39;s own directory. That matters, because <code>launchProgram</code> reads <code>package.json</code> and writes <code>.mock-cache</code> in the current working directory.</p><p><code>start</code> stays as it was. Keep it separate if you use it for day-to-day work against a real API, so it doesn&#39;t need the holodeck certificate.</p><h2 id="things-to-know" tabindex="-1">Things to know <a class="header-anchor" href="#things-to-know" aria-label="Permalink to “Things to know”">​</a></h2><ul><li>A dev run records fixtures, just like a local <code>pnpm test</code>. Holodeck records unless <code>CI</code> is set, and every test that reaches a <code>mock()</code> writes its fixture into <code>.mock-cache</code>. Check <code>git status</code> before you commit, as you would after a local test run. See <a href="/pr-preview/pr-11205/guides/the-manual/testing/record-and-replay">Record and replay</a>.</li><li>Stop <code>test:dev</code> before running <code>pnpm test</code>. Both launch holodeck on the same port. The second one retries the bind a few times and then exits with <code>Error: listen EADDRINUSE: address already in use ::1:7358</code>. See <a href="/pr-preview/pr-11205/guides/the-manual/testing/troubleshooting#the-port-was-taken">The port was taken</a>.</li><li>If <code>Failed to fetch</code> or <code>Load failed</code> persists while holodeck&#39;s banner shows it running, the browser you opened <code>/tests</code> in does not trust the certificate. See <a href="/pr-preview/pr-11205/guides/the-manual/testing/server-setup#trust-a-local-certificate">Trust a local certificate</a>.</li><li>Apps that serve their tests with <code>@warp-drive/diagnostic</code> don&#39;t hit this. Its <code>launch()</code> starts holodeck from its <code>setup</code> hook every time the suite runs.</li><li>The page on <code>4200</code> still reaches holodeck on <code>7358</code>, so every mocked request is cross-origin. <a href="/pr-preview/pr-11205/guides/the-manual/testing/common-setups/">Common setups</a> puts the mock server on the page&#39;s own origin, from Vite, from testem, or behind Caddy, with no preflight <code>OPTIONS</code> requests.</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};